import { Body, Controller, Headers, HttpStatus, Post, Res } from "@nestjs/common";
import {OrganizationCreateValidator} from "@crosspublic/validators/src/organizations/organization.create.validator";
import {OrganizationService} from "@crosspublic/database/src/organization/organization.service";
import {UserService} from "@crosspublic/database/src/users/user.service";
import {ApiOperation, ApiTags} from "@nestjs/swagger";
import {RegistrationValidator} from "@crosspublic/validators/src/auth/registration.validator";
import {Response} from "express";
import {AuthService} from "@crosspublic/helpers/src/auth/auth.service";
import {removeSubdomain} from "@crosspublic/helpers/src/subdomain/subdomain.management";
import {LoginValidator} from "@crosspublic/validators/src/auth/login.validator";
import {compareSync} from "bcrypt";
import {IntegrationsService} from "@crosspublic/database/src/integrations/integrations.service";
import { AuthIntegrationValidator } from "@crosspublic/validators/src/auth/auth.integration.validator";
@ApiTags('Authentications')
@Controller('/auth')
export class AuthController {
  constructor(
    private _organizationService: OrganizationService,
    private _userService: UserService,
    private _integrationService: IntegrationsService,
  ) {
  }
  @ApiOperation({summary: 'Check org and user', description: 'Checking that the bot that in the server is actually authenticated'})
  @Post('/')
  async checkOrgAndUser(
    @Body() body: OrganizationCreateValidator,
    @Headers('serverkey') serverkey: string
  ) {
    if (serverkey !== process.env.BACKEND_TOKEN_PROTECTOR) {
      return 401;
    }
    const user = await this._integrationService.findByGuildAndId(body.guildId, body.internalId);
    if (!user?.users?.[0]) {
      return ;
    }

    const organization = await this._organizationService.getOrgById(user.organizationId);
    return {
      organization: {
        organizationId: organization.id,
      }
    }
  }

  @ApiOperation({summary: 'Get integration auth object', description: 'Getting the object of a specific auth'})
  @Post('/integration')
  async getIntegrationAuthObject(
    @Body() body: AuthIntegrationValidator,
    @Headers('serverkey') serverkey: string
  ) {
    if (serverkey !== process.env.BACKEND_TOKEN_PROTECTOR) {
      return 401;
    }

    return this._integrationService.getAuthObject(body);
  }

  @ApiOperation({summary: 'Register to crosspublic', description: 'This will create an organization and a user'})
  @Post('/registration')
  async register(
    @Body() body: RegistrationValidator,
    @Res() res: Response
  ) {
    const register = await this._organizationService.register(body);
    const obj = {
      id: register.id,
      email: register.email,
      name: register.name,
      organization: register.organization[0],
    }

    res.cookie('auth', AuthService.signJWT(obj), {
      path: '/',
      sameSite: false,
      // secure: true,
      httpOnly: true,
      domain: '.' + new URL(removeSubdomain(process.env.FRONTEND_URL!)).hostname
    });

    return res.status(HttpStatus.OK).json({created: true});
  }

  @ApiOperation({summary: 'Login to crosspublic', description: 'This will login the user'})
  @Post('/login')
  async login(
    @Body() body: LoginValidator,
    @Res() res: Response
  ) {
    const user = await this._userService.getUserByEmail(body.email);
    if (!user) {
      return res.status(HttpStatus.UNAUTHORIZED).json({error: 'Invalid credentials'});
    }

    if (!compareSync(body.password, user.password)) {
      return res.status(HttpStatus.UNAUTHORIZED).json({error: 'Invalid credentials'});
    }

    const obj = {
      id: user.id,
      email: user.email,
      name: user.name,
      organization: user.organization[0]
    }

    res.cookie('auth', AuthService.signJWT(obj), {
      path: '/',
      sameSite: false,
      // secure: true,
      httpOnly: true,
      domain: '.' + new URL(removeSubdomain(process.env.FRONTEND_URL!)).hostname
    });

    return res.status(HttpStatus.OK).json({created: true});
  }
}

import {Body, Controller, Get, Param, Post} from "@nestjs/common";
import {SubscriptionService} from "@crosspublic/database/src/subscription/subscription.service";
import {GetUserFromRequest} from "@crosspublic/helpers/src/user/user.from.request";
import {UserInterface} from "@crosspublic/helpers/src/user/user.interface";
import {BillingSubscribeValidator} from "@crosspublic/validators/src/billing/billing.subscribe.validator";
import {StripeService} from "@crosspublic/helpers/src/stripe/stripe.service";
import {IdStringValidator} from "@crosspublic/validators/src/general/id.string.validator";
import {ApiHeaders, ApiOperation, ApiTags} from "@nestjs/swagger";

@ApiTags('Billings')
@Controller('/billing')
@ApiHeaders([{name: 'auth', required: true}])
export class BillingController {
  constructor(
    private _subscriptionService: SubscriptionService,
    private _stripeService: StripeService,
  ) {
  }

  @Get('/check/:id')
  async checkId(
    @GetUserFromRequest() user: UserInterface,
    @Param() body: IdStringValidator
  ) {
    return {exists: !!await this._subscriptionService.checkSubscription(user.organization.organizationId, body.id)};
  }

  @ApiOperation({summary: 'Subscribe to a plan', description: 'Subscribe to a plan'})
  @Post('/subscribe')
  subscribe(
    @GetUserFromRequest() user: UserInterface,
    @Body() body: BillingSubscribeValidator
  ) {
    return this._stripeService.subscribe(user.organization.organizationId, body);
  }

  @Post('/modify')
  async modifyPayment(
    @GetUserFromRequest() user: UserInterface,
  ) {
    const customer = await this._stripeService.getCustomerByOrganizationId(user.organization.organizationId);
    const {url} = await this._stripeService.createBillingPortalLink(customer);
    return {
      portal: url
    }
  }

  @Get('/')
  getCurrentBilling(
    @GetUserFromRequest() user: UserInterface
  ) {
    return this._subscriptionService.getSubscriptionByOrganizationId(user.organization.organizationId);
  }

  @Post('/cancel')
  cancel(
    @GetUserFromRequest() user: UserInterface,
  ) {
    return this._stripeService.setToCancel(user.organization.organizationId);
  }
}

const process = require('process')
process.chdir(__dirname);
const {writeFileSync, renameSync, rmdirSync, mkdirSync} = require("fs");
const { config } = require('dotenv');
const prod = require('./mint.js').default;
config();
(async () => {
  const {generateOpenApiPages} = await import("@mintlify/scraping");

  try {
    rmdirSync('./api-reference/custom', { recursive: true });
    rmdirSync('./public-api-reference/custom', { recursive: true });
    await new Promise((resolve) => setTimeout(resolve, 2000));
  } catch (e) {
  }

  await generateOpenApiPages(process.env.BACKEND_URL + '/docs-json', true, 'api-reference/custom');
  const generate = await generateOpenApiPages(process.env.BACKEND_URL + '/docs-json');
  await new Promise((resolve) => setTimeout(resolve, 3000));

  mkdirSync('./public-api-reference/custom', { recursive: true });
  renameSync('./api-reference/custom/public', './public-api-reference/custom/public/');

  prod.navigation.push(...generate.nav.map((item) => ({
    ...item,
    pages: item.pages.map((page) => (page.indexOf('public') >  -1 ? 'public-api-reference/custom/' : 'api-reference/custom/') + page)
  })));

  writeFileSync('./mint.json', JSON.stringify(prod, null, 2));
  const text = await (await fetch(process.env.BACKEND_URL + '/docs-json')).text();
  writeFileSync('./openapi.json', text);
})();
